        final_cursor = probed.get("CURSOR_PRESENT", probed.get("CURSOR_AVAILABLE", ""))
        final_codex_bin = probed.get("CODEX_BINARY_FOUND", "")
        final_cursor_bin = probed.get("CURSOR_BINARY_FOUND", "")
    else:
